insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('78444887-ae32-4b6e-800a-f2a0719571e9', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La tabla muestra dos modelos que explican cómo pueden generarse especies distintas a partir de una misma especie. Se encontró una especie de murciélago que habita solo en la parte alta de una cadena montañosa. Después de unos análisis de ADN, se encontró que esta especie es muy cercana a una especie que solo vive en la parte baja de la cadena montañosa y de la cual se tiene registros de su existencia más antiguos que la de alta montaña.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-q97.webp" style="min-width:440px" loading="lazy" alt="Dos modelos: separación por barrera geográfica y formación de dos especies en un mismo espacio."><figcaption>Dos modelos: separación por barrera geográfica y formación de dos especies en un mismo espacio. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('c1cebd02-885c-44e9-90a6-6a488dfe2dfc', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un grupo de investigadores desarrolló un plaguicida para combatir una plaga específica presente en un cultivo de arroz. Realizaron una primera aplicación y obtuvieron como resultado que el 80% de la plaga fue eliminada, por lo que los investigadores afirmaron que su tratamiento era efectivo.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9d935d62-8e11-4259-919c-c4592ee863ab', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El cáncer de cuello uterino en mujeres está asociado con el virus del papiloma humano. La detección del virus se realiza directamente sobre células del cuello uterino, debido a que este virus no circula por el torrente sanguíneo u otros fluidos corporales. Como medida de prevención de este tipo de cáncer se ha realizado campañas de vacunación sobre todo en mujeres que no han iniciado su vida sexual, cuando la vacuna es más efectiva.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d812cce6-c708-46e3-9210-3586e1727b0c', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La figura muestra las diferencias en la corteza cerebral y las neuronas de un individuo sano, y uno con la enfermedad de Alzhéimer.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-q100.webp" style="min-width:760px" loading="lazy" alt="Funciones de regiones cerebrales y comparación entre cerebro saludable y cerebro con alzhéimer."><figcaption>Funciones de regiones cerebrales y comparación entre cerebro saludable y cerebro con alzhéimer. Desliza para ver la figura completa.</figcaption></figure><p>El Alzhéimer es una enfermedad caracterizada por el deterioro de la memoria, pérdida de la atención y trastornos en la manera de actuar. Estos síntomas se dan por la gran pérdida de neuronas y porque se atrofian diferentes zonas del cerebro.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('292425bd-40c3-4e23-9fbf-7a46d41fcf12', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Algunas especies de aves que habitan latitudes cercanas a los polos permanecen allí durante el verano, donde se producen, anidan y cuidan a sus pichones. Cuando termina el verano, estas aves migran con sus crías a latitudes tropicales. Muchas de las plantas que consumen estas aves en los ecosistemas cercanos a los polos, ahora se encuentran en regiones más tropicales, a muchos kilómetros de su hábitat original. Unos investigadores detectaron que las semillas de estas plantas no son destruidas por las aves durante la digestión, sino que pasan intactas por el tracto digestivo.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('342eb502-b27a-4c42-96aa-94bbe0b0b62c', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El modelo muestra el proceso de formación del gas natural, del petróleo y del carbón.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-q103.webp" style="min-width:640px" loading="lazy" alt="Acumulación y enterramiento de materia orgánica durante millones de años; formación de gas, petróleo y carbón."><figcaption>Acumulación y enterramiento de materia orgánica durante millones de años; formación de gas, petróleo y carbón. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('22a5a296-29d1-4f41-90c3-ee6fa8975d13', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En un ecosistema, la dispersión de semillas de algunas plantas se realiza a través de aves que consumen sus frutos. Luego de digerir los frutos, las aves depositan las semillas en el suelo a través de su excremento. Unos pobladores introdujeron una especie de mamífero que se alimenta de los huevos de estas aves, lo cual ha causado una disminución considerable de ellas en el ecosistema.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('495c81cb-bcb8-4298-8241-b323186a475a', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Unos estudiantes deben realizar un experimento para medir el crecimiento bacteriano en un medio de cultivo rico en proteínas. Para ello se distribuyeron en dos grupos de estudiantes y midieron las variables que muestra la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Variable</th><th scope="col">Grupo de estudiantes 1</th><th scope="col">Grupo de estudiantes 2</th></tr></thead><tbody><tr><th scope="row">Temperatura</th><td>37 °C</td><td>37 °C</td></tr><tr><th scope="row">Nutrientes</th><td>Cultivo con 25% de proteína animal, agua y sales minerales</td><td>Cultivo con 25% de proteína animal, agua y sales minerales</td></tr><tr><th scope="row">pH del medio de cultivo</th><td>7</td><td>7</td></tr><tr><th scope="row">Frascos de cultivos analizados</th><td>3</td><td>3</td></tr><tr><th scope="row">Conteo de bacterias en el medio</th><td>Cada 2 horas</td><td>Cada 30 minutos</td></tr><tr><th scope="row">Tiempo que duró el experimento</th><td>2 horas</td><td>20 horas</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4aec2116-2a6f-4b4d-993d-c2eeb82f9636', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Los habitantes de una población usan la laguna local para actividades recreativas como nadar y pescar. En los últimos meses, los habitantes han presentado una reacción alérgica en la piel, luego de haber nadado en la laguna.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('06ffa744-b20c-4fe2-b21e-f83bec8b4eea', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La metamorfosis de algunas ranas empieza al final de la etapa de renacuajos, quienes son acuáticos y respiran mediante branquias. En esta etapa se desarrollan las patas posteriores y luego las patas anteriores. Antes de emerger del agua, se degeneran las branquias, se agrandan los pulmones y la cola se reabsorbe. Al final de la metamorfosis la rana se transforma en un animal terrestre y puede reproducirse.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ecd3e04b-ffe2-44a0-bf01-2bcfb29f7950', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Los leones son grandes carnívoros, viven en manadas y habitan en las sabanas. Una población de leones caza únicamente presas grandes como antílopes y cebras, y con ellos se alimentan los leones adultos y sus crías. Un grupo de leopardos fue liberado en este hábitat, los cuales cazan el mismo tipo de presas que los leones, lo que generó una competencia entre especies por el alimento.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('03d40744-6c2d-4ca3-8637-68ff6ea430be', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El diente de león es una planta que se cree es originaria de Europa, aunque su área de distribución actualmente abarca casi la totalidad de los pastizales y jardines de todos los continentes. La figura muestra el diente de león y sus partes.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-q109.webp" style="min-width:360px" loading="lazy" alt="Diente de león: receptáculo, cipselas, semilla, flor, hojas y frutos."><figcaption>Diente de león: receptáculo, cipselas, semilla, flor, hojas y frutos. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f4213082-77d4-4522-a5bb-da29110af502', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Las gráficas 1 y 2 muestran la relación entre la temperatura corporal y la temperatura ambiental (1) y la relación entre la actividad metabólica y la temperatura corporal (2).</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-q110.webp" style="min-width:700px" loading="lazy" alt="Gráfica 1: temperatura corporal frente a temperatura ambiente. Gráfica 2: tasa metabólica frente a temperatura corporal; ambas relaciones son crecientes."><figcaption>Gráfica 1: temperatura corporal frente a temperatura ambiente. Gráfica 2: tasa metabólica frente a temperatura corporal; ambas relaciones son crecientes. Desliza para ver la figura completa.</figcaption></figure><p>Un reptil necesita regular su temperatura para aumentar su actividad metabólica, poder cazar algunas presas y alimentarse.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('42731ad8-4569-4eb8-a69f-d8832ba693f0', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La coevolución ocurre cuando dos o más especies se encuentran estrechamente relacionadas, lo que provoca la generación de cambios evolutivos en paralelo. En otras palabras, un cambio evolutivo en una de las especies involucradas influye para provocar un cambio evolutivo en la otra especie y viceversa.</p><p>Las interacciones que con más frecuencia dan origen a la coevolución son: el mutualismo (interacción ecológica en la que las dos especies se benefician) y la depredación (cazador–presa). Las figuras 1, 2, 3 y 4 muestran diferentes relaciones entre algunas especies en la naturaleza.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-q111.webp" style="min-width:440px" loading="lazy" alt="1: insecto polinizador y flor. 2: osos polar y pardo, ambos carnívoros. 3: rinoceronte e hipopótamo, ambos herbívoros. 4: liquen, asociación entre hongo y alga."><figcaption>1: insecto polinizador y flor. 2: osos polar y pardo, ambos carnívoros. 3: rinoceronte e hipopótamo, ambos herbívoros. 4: liquen, asociación entre hongo y alga. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('19f60c19-bb00-4556-b134-0c0b6336927a', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La radiación ionizante puede consistir en partículas Alfa (α) y beta (β), así como en rayos Gamma (γ) y en rayos x. La figura muestra su poder de penetración en diferentes materiales, los cuales aumentan de izquierda a derecha su grosor. Uno de los peligros del uso de la radiación ionizante es su alto potencial de alteración del ADN de las células, por lo que se considera un agente cancerígeno.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-qradiacion.webp" style="min-width:470px" loading="lazy" alt="Penetración de radiaciones alfa, beta, X y gamma en papel, aluminio, plomo y hormigón."><figcaption>Penetración de radiaciones alfa, beta, X y gamma en papel, aluminio, plomo y hormigón. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('18c9cd48-8c0c-4ade-8be6-32bb38ee65df', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un estudiante quiere determinar qué tipo de leche se recomienda para la salud de una persona que sufre de sobrepeso. Para ello, identifica los componentes de dos tipos de leche del mercado y obtiene los resultados que se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Componentes en 100 ml</th><th scope="col">Leche 1</th><th scope="col">Leche 2</th></tr></thead><tbody><tr><th scope="row">Proteínas</th><td>3,1 g</td><td>3,2 g</td></tr><tr><th scope="row">Carbohidratos</th><td>6,9 g</td><td>3,6 g</td></tr><tr><th scope="row">Grasas</th><td>3,6 g</td><td>0,2 g</td></tr><tr><th scope="row">Calcio</th><td>0,2 g</td><td>0,1 g</td></tr></tbody></table></div><p>De acuerdo con los resultados obtenidos, el estudiante concluye: «Cualquiera de los dos tipos de leche es recomendable para una persona con sobrepeso, porque los dos tipos de leche analizados presentan calcio». Una nutricionista le indica que una persona con sobrepeso debe disminuir en su dieta el consumo de grasas y de carbohidratos.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('74d2c01d-c62d-4040-9f6a-7e536f0b9ac4', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Miguel realiza actividades físicas que requieren una gran cantidad de energía. Él quiere conocer qué alimentos son más apropiados para consumir antes de realizar sus actividades físicas y que, a la vez, le proporcionen una alimentación balanceada. Él consulta la siguiente tabla:</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Tipo de alimento</th><th scope="col">Alimento</th><th scope="col">Calorías por porción</th></tr></thead><tbody><tr><th scope="row">Leche y sus derivados</th><td>Leche entera</td><td>490</td></tr><tr><th scope="row">Leche y sus derivados</th><td>Yogurt</td><td>62</td></tr><tr><th scope="row">Leche y sus derivados</th><td>Queso</td><td>300</td></tr><tr><th scope="row">Productos cárnicos</th><td>Carne de cerdo</td><td>375</td></tr><tr><th scope="row">Productos cárnicos</th><td>Carne de vaca</td><td>120</td></tr><tr><th scope="row">Productos cárnicos</th><td>Pollo</td><td>160</td></tr><tr><th scope="row">Frutos secos</th><td>Almendras</td><td>480</td></tr><tr><th scope="row">Frutos secos</th><td>Maní</td><td>560</td></tr><tr><th scope="row">Frutos secos</th><td>Nueces</td><td>600</td></tr><tr><th scope="row">Verduras</th><td>Espinaca</td><td>20</td></tr><tr><th scope="row">Verduras</th><td>Alcachofas</td><td>50</td></tr><tr><th scope="row">Verduras</th><td>Acelgas</td><td>22</td></tr></tbody></table></div>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'faed1d27-f447-4d2e-b6ab-02a1d61d08c0', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'evolucion'),
  (select id from public.lotes where codigo = '2026-B'),
  '78444887-ae32-4b6e-800a-f2a0719571e9', 'Evolución y biodiversidad',
  'Si se sabe que hay especies de murciélagos en la parte media de la montaña, ¿cuál de los dos modelos permitiría explicar que la especie de la parte alta de la montaña desciende de la especie de baja montaña?',
  array['Alopátrica, porque las dos especies pueden aún tener descendencia entre ellas.', 'Simpátrica, porque las poblaciones habitan en el mismo espacio geográfico.', 'Simpátrica, porque las especies habitan a lo largo de la cadena montañosa.', 'Alopátrica, porque las poblaciones están divididas por una barrera geográfica.'],
  'Distingue presencia de otras especies y continuidad de las poblaciones estudiadas.', 'borrador', 'modelo', 'f7d1d051eb6a17accf27cf2f7430ae74', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('faed1d27-f447-4d2e-b6ab-02a1d61d08c0', 2, 'El enunciado parece orientar a continuidad de distribución en la cadena montañosa, pero no indica si los murciélagos de la zona media pertenecen a las poblaciones descritas ni establece flujo génico. La altitud también aparece como barrera en la tabla. Se requiere aclaración o clave docente antes de publicar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5ce2f5db-ef73-4cca-946c-4cbe3aae8c42', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'c1cebd02-885c-44e9-90a6-6a488dfe2dfc', 'Ecosistemas y ciclos',
  '¿Qué deben hacer los investigadores para estar seguros del porcentaje de eficacia del plaguicida en los cultivos de arroz?',
  array['Contar el número de hojas que tienen todas las plantas del cultivo y estimar un promedio.', 'Determinar el tipo de célula que conforma la plaga en el cultivo de arroz y compararla con el de la planta de arroz.', 'Determinar la cantidad de arroz que se produce todos los meses del año y estimar la pérdida por la plaga.', 'Hacer aplicaciones del plaguicida en otros cultivos de arroz de la zona y comparar los resultados.'],
  'Busca una repetición del experimento que permita comparar resultados.', 'publicada', 'modelo', '086e2b2792f858863aa241faf2d2b0ff', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5ce2f5db-ef73-4cca-946c-4cbe3aae8c42', 3, 'Repetir la prueba en otros cultivos permite comprobar si el porcentaje observado se reproduce. Las otras mediciones no contrastan directamente la eficacia del tratamiento.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '99f9b481-a490-4169-8cd0-aaa42efefdc3', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  '9d935d62-8e11-4259-919c-c4592ee863ab', 'Sistemas del cuerpo humano',
  'Además de la vacunación, otra medida para la prevención contra el cáncer de cuello uterino es',
  array['no compartir elementos como cuchillas de afeitar o cepillos de dientes.', 'aplicar espermicidas antes de mantener una relación sexual.', 'utilizar preservativo o condones durante la relación sexual.', 'ingerir pastillas anticonceptivas previo a la relación sexual.'],
  'Distingue evitar un embarazo de reducir una infección de transmisión sexual.', 'publicada', 'modelo', 'd2b88d35f910242e996faa4a16b7b766', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('99f9b481-a490-4169-8cd0-aaa42efefdc3', 2, 'El preservativo puede reducir el riesgo de transmisión sexual del VPH, aunque no lo elimina porque no cubre toda la piel que puede estar infectada. Los anticonceptivos y espermicidas no equivalen a protección frente a esta infección.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b3bf571d-95e9-462a-a5af-353e02a81cdf', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  'd812cce6-c708-46e3-9210-3586e1727b0c', 'Sistemas del cuerpo humano',
  'Con base en la información anterior, ¿qué otro daño es inmediato en una persona con Alzhéimer?',
  array['Pérdida de la regulación de la temperatura en el cuerpo.', 'Pérdida de la sensación en las manos, brazos y piernas.', 'Disminución de la velocidad de procesamiento de la información de los sentidos.', 'Disminución de los movimientos involuntarios en el corazón y los pulmones.'],
  'Relaciona la región que aparece deteriorada con la función que se le atribuye.', 'publicada', 'modelo', '2d9dcfe21e1cdde42e2d8cd1a73440c8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b3bf571d-95e9-462a-a5af-353e02a81cdf', 2, 'La figura relaciona la corteza con procesar la percepción sensorial y muestra su disminución en el cerebro afectado. La respuesta se deduce del modelo del ejercicio, sin convertirlo en un pronóstico clínico individual.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0cab4cbe-933e-404b-8fed-a698ee012e1a', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '292425bd-40c3-4e23-9fbf-7a46d41fcf12', 'Ecosistemas y ciclos',
  '¿Cuál de las siguientes razones puede explicar la reciente aparición de estas plantas en ecosistemas más tropicales?',
  array['Los frutos de estas plantas se mueven por los ríos y los mares, cuando llegan al trópico germinan.', 'Algunas plantas de otros ecosistemas le sirven de alimento al ave durante su recorrido hasta las zonas tropicales.', 'Muchas veces llevan pedazos de hojas y pedazos de flores en el pico y las dejan caer durante su vuelo en otros ecosistemas.', 'Muchas aves terminan de digerir los frutos durante el vuelo de migración y dejan caer las semillas con excremento en otros ecosistemas.'],
  'Relaciona migración, digestión y semillas intactas.', 'publicada', 'modelo', '1a9eb6947ca3aba9b760f470d00bd0ff', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0cab4cbe-933e-404b-8fed-a698ee012e1a', 3, 'La supervivencia de las semillas al paso por el tracto digestivo permite que las aves las depositen en otro ecosistema durante la migración. Es el mecanismo que conecta los datos del enunciado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '658ec1bd-5d1b-4ac9-83a9-c28a4b3cae9c', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '342eb502-b27a-4c42-96aa-94bbe0b0b62c', 'Ecosistemas y ciclos',
  'Con base en la información anterior, se puede afirmar que el gas, el petróleo y el carbón se originan por:',
  array['La descomposición de los ríos, lagunas y mares hace millones de años.', 'La acumulación de materia orgánica bajo los sedimentos, por millones de años.', 'La ubicación de torres que perforan las capas del suelo hace millones de años.', 'La mezcla de tierra y agua en un solo compuesto, por millones de años.'],
  'Distingue la formación del recurso de su extracción.', 'publicada', 'modelo', 'd64de6ed66d88249e134f68a65d8f05e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('658ec1bd-5d1b-4ac9-83a9-c28a4b3cae9c', 1, 'El modelo vincula restos de seres vivos, enterramiento y largos periodos de transformación. Las torres extraen los combustibles; no los originan.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '64096600-4b4c-4602-b39a-e19b5fe34a85', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '22a5a296-29d1-4f41-90c3-ee6fa8975d13', 'Ecosistemas y ciclos',
  'Con base en la información anterior, ¿cuál de las siguientes razones sería una posible consecuencia de la disminución de estas aves en el ecosistema?',
  array['La cantidad de frutos producidas por las plantas aumentará, y por tanto el mamífero tendrá más disponibilidad de alimento.', 'La cantidad de semillas dispersadas por las aves que consumían estos frutos disminuirá en el ecosistema.', 'La cantidad de plantas presentes en el ecosistema que convive con el ave aumentará al disminuir su depredación.', 'La cantidad de mamíferos disminuirá, porque empezarán a dispersar las semillas de las plantas del ecosistema.'],
  'Sigue la relación entre el número de dispersores y las semillas transportadas.', 'publicada', 'modelo', '81125446838254511fd2553b1990dfd9', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('64096600-4b4c-4602-b39a-e19b5fe34a85', 1, 'Al disminuir las aves que transportan semillas en sus excrementos, disminuye ese mecanismo de dispersión. El mamífero descrito come huevos, no frutos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '63cf346d-49c1-47af-a1b3-ad2f27e5ac69', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  '495c81cb-bcb8-4298-8241-b323186a475a', 'Célula y sus procesos',
  'Con base en la información anterior, ¿cuál de los dos experimentos arrojaría resultados más confiables?',
  array['El primero, porque al realizar el conteo en periodos más largos se interfiere menos en el crecimiento bacteriano.', 'El segundo, porque tenía mejores condiciones en el medio de cultivo para el crecimiento bacteriano.', 'El primero, porque los datos se tomaron teniendo en cuenta el periodo de división celular y se contrastó con más frascos.', 'El segundo, porque los datos se obtienen en periodos cortos y durante un tiempo más largo.'],
  'Compara las filas que realmente cambian entre los grupos.', 'publicada', 'modelo', 'f51fa25ac7bd4c372edaa9b4cf3cc13c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('63cf346d-49c1-47af-a1b3-ad2f27e5ac69', 3, 'Los medios y el número de frascos son iguales. El segundo grupo observa durante más tiempo y con mayor frecuencia, por lo que describe mejor la evolución del crecimiento.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7e814f62-5643-48ec-85ff-3c953bb3f677', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '4aec2116-2a6f-4b4d-993d-c2eeb82f9636', 'Ecosistemas y ciclos',
  'Teniendo en cuenta la información anterior, la pregunta que desde el campo de las Ciencias Naturales podría resolverse es:',
  array['¿Cuál es la actividad recreativa de mayor importancia para los habitantes?', '¿Cómo educar a los habitantes de la población para que no naden en la laguna?', '¿Cómo son las ventas de medicamentos antialérgicos en los pueblos cercanos a la laguna?', '¿Cuál es el componente dentro del agua de la laguna que causa la alergia en la piel?'],
  'Busca una causa física, química o biológica que pueda investigarse.', 'publicada', 'modelo', '7888d11cc43852fe80e3cd906bec4a25', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7e814f62-5643-48ec-85ff-3c953bb3f677', 3, 'Identificar una sustancia o agente del agua y estudiar su relación con la reacción cutánea es una investigación sobre fenómenos naturales. Las otras preguntas abordan preferencias, educación o ventas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9eb54b1b-9dfb-45d4-8fea-80ebdc7e5c2a', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'evolucion'),
  (select id from public.lotes where codigo = '2026-B'),
  '06ffa744-b20c-4fe2-b21e-f83bec8b4eea', 'Evolución y biodiversidad',
  'Con base en la información anterior, ¿cuál de los siguientes modelos muestra la metamorfosis de este tipo de ranas?',
  array['<img src="img/figuras/bio/b1-q107-a.webp" alt="Modelo de metamorfosis: secuencia de etapas conectadas por flechas" style="width:100%;max-width:360px" loading="lazy">', '<img src="img/figuras/bio/b1-q107-b.webp" alt="Modelo de metamorfosis: secuencia de etapas conectadas por flechas" style="width:100%;max-width:360px" loading="lazy">', '<img src="img/figuras/bio/b1-q107-c.webp" alt="Modelo de metamorfosis: secuencia de etapas conectadas por flechas" style="width:100%;max-width:360px" loading="lazy">', '<img src="img/figuras/bio/b1-q107-d.webp" alt="Modelo de metamorfosis: secuencia de etapas conectadas por flechas" style="width:100%;max-width:360px" loading="lazy">'],
  'Sigue las flechas y verifica el orden de aparición de las patas.', 'publicada', 'modelo', '54ae0e2ad93aaac6ff876109d43e5758', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9eb54b1b-9dfb-45d4-8fea-80ebdc7e5c2a', 2, 'La secuencia coherente pasa de huevos a renacuajo, desarrolla primero patas posteriores y después anteriores y termina con la reabsorción de la cola. El modelo seleccionado conserva ese orden.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '781c60d8-3e13-4c6c-85c8-d62f34d125a2', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'ecd3e04b-ffe2-44a0-bf01-2bcfb29f7950', 'Ecosistemas y ciclos',
  'De acuerdo con la información anterior, ¿qué le puede ocurrir a la población de leones, a largo plazo, producto de esta competencia entre especies?',
  array['Los leones serán más grandes y gordos porque les será más fácil conseguir alimento.', 'La población de leones tendrá menos individuos porque el alimento disponible disminuirá en la sabana.', 'La población de leones tendrá más individuos porque se volverán herbívoros para disminuir la competencia.', 'La población de leones tendrá crías con la población de leopardos para poblar la sabana con una nueva especie.'],
  'Sigue el efecto de compartir un recurso alimentario limitado.', 'publicada', 'modelo', '435a8e0e4af246c624669b6f480776b5', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('781c60d8-3e13-4c6c-85c8-d62f34d125a2', 1, 'Si dos depredadores compiten por las mismas presas, puede disminuir el alimento disponible para cada población y, con él, la supervivencia o reproducción de los leones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3847da22-d8be-4557-84b6-62d8080dc497', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'evolucion'),
  (select id from public.lotes where codigo = '2026-B'),
  '03d40744-6c2d-4ca3-8637-68ff6ea430be', 'Evolución y biodiversidad',
  'Con base en la información anterior, ¿por qué todos los continentes tienen en sus pastizales al diente de león?',
  array['Porque sus semillas se dispersan fácilmente con el viento y tienen una alta tolerancia a distintas condiciones ambientales.', 'Porque los pastizales de los distintos continentes se localizan a la misma latitud y altitud en todo el planeta.', 'Porque el diente de león es una planta pequeña y herbácea que puede transportarse fácilmente por animales carnívoros.', 'Porque el diente de león, al ser un organismo autótrofo, produce sus propios nutrientes a partir de la luz del sol.'],
  'Relaciona la estructura de los frutos con su transporte.', 'publicada', 'modelo', '7dde2f5b38411c3f3876ebe0cd89aeb8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3847da22-d8be-4557-84b6-62d8080dc497', 0, 'Los frutos ligeros con estructuras semejantes a un paracaídas facilitan la dispersión por el viento. La tolerancia a ambientes diversos ayuda a explicar el establecimiento en muchos lugares; ser autótrofa no basta para explicar esa distribución.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '673694db-ab13-48b8-b7ec-d70833f26d79', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'evolucion'),
  (select id from public.lotes where codigo = '2026-B'),
  'f4213082-77d4-4522-a5bb-da29110af502', 'Evolución y biodiversidad',
  'Teniendo en cuenta la información anterior, ¿en qué situación se espera que sea mayor la tasa metabólica?',
  array['Cuando hay mayor cantidad de lluvia que disminuye la temperatura corporal.', 'Cuando hay mayor cantidad de sol que aumenta la temperatura corporal.', 'Cuando hay mayor cantidad de sombra que disminuye la temperatura corporal.', 'Cuando hay mayor cantidad de viento que aumenta la temperatura corporal.'],
  'Relaciona las dos gráficas y el efecto del sol.', 'publicada', 'modelo', 'cafbeefe867a83571649bfc04510368c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('673694db-ab13-48b8-b7ec-d70833f26d79', 1, 'En las gráficas, al aumentar la temperatura corporal aumenta la tasa metabólica. Recibir más sol permite al reptil elevar su temperatura en las condiciones planteadas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3b28b8ff-8e74-4b8a-ace1-8cf21e81b004', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'evolucion'),
  (select id from public.lotes where codigo = '2026-B'),
  '42731ad8-4569-4eb8-a69f-d8832ba693f0', 'Evolución y biodiversidad',
  'De las parejas de especies anteriores, ¿cuáles podrían ser casos de coevolución?',
  array['1 y 3', '2 y 3', '1 y 4', '2 y 4'],
  'Busca interacciones directas, no solo semejanzas en la alimentación.', 'publicada', 'modelo', '39ffd614cce8c5a9e7ba549119ea9df4', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3b28b8ff-8e74-4b8a-ace1-8cf21e81b004', 2, 'El polinizador y la flor, y el hongo y el alga del liquen, mantienen asociaciones estrechas que pueden ejercer presiones selectivas recíprocas. Compartir una dieta no demuestra esa relación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '09f64fb4-b432-4cee-bc3a-66acd9fb9abc', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '19f60c19-bb00-4556-b134-0c0b6336927a', 'Genética y herencia',
  'El cáncer es una enfermedad en la que las células de los tejidos se transforman y ya no son reconocidas por el tejido. Estas células desplazan las células sanas, porque se dividen más rápidamente. En los exámenes que se realizan para diagnosticar el cáncer, no se usan los rayos x y los rayos γ. ¿Cuál sería una consecuencia negativa de diagnosticar el cáncer con rayos x o γ?',
  array['La generación de más células cancerígenas, por la posibilidad que tienen de alterar su material genético.', 'La reducción de las células del tejido canceroso, por la posibilidad de dañar los organelos y membranas celulares.', 'La generación de muerte celular en los tejidos, por el aluminio que se usa como barrera de protección.', 'La reducción del tejido canceroso, por la posibilidad de transformar las células cancerosas en células normales.'],
  'Distingue un riesgo potencial de la afirmación incorrecta sobre el uso diagnóstico.', 'borrador', 'modelo', 'ba61718c7966faab98f9383715aa56ab', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('09f64fb4-b432-4cee-bc3a-66acd9fb9abc', 0, 'La radiación ionizante puede dañar el ADN, pero la premisa de que no se usan rayos X para diagnosticar cáncer es falsa: la tomografía y otros estudios radiológicos forman parte del diagnóstico. Se conserva en borrador para corregir esa premisa antes de usarla. Fuente de contraste: Instituto Nacional del Cáncer, «Cómo se diagnostica el cáncer».');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '859beb34-1199-4297-a41a-82b5b8f5ead1', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  '18c9cd48-8c0c-4ade-8be6-32bb38ee65df', 'Sistemas del cuerpo humano',
  'De acuerdo con la información anterior, ¿cuál de las siguientes es una conclusión coherente con los resultados del estudiante?',
  array['La leche 2 se recomienda para una persona con sobrepeso, porque contiene menos cantidad de grasas y carbohidratos que la leche 1.', 'La leche 1 se recomienda para una persona con sobrepeso, porque contiene una menor cantidad de proteínas que la leche 2.', 'La leche 2 se recomienda para una persona con sobrepeso, porque contiene más grasas y carbohidratos en 100 ml que la leche 1.', 'La leche 1 se recomienda para una persona con sobrepeso, porque contiene una mayor cantidad de calcio que la leche 2.'],
  'Compara las mismas cantidades de leche y las dos variables indicadas.', 'publicada', 'modelo', '26b528cefba0ccaab07e4cfd4e0c9d8d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('859beb34-1199-4297-a41a-82b5b8f5ead1', 0, 'Según el criterio dado en el ejercicio, la leche 2 tiene menos grasas (0,2 frente a 3,6 g) y carbohidratos (3,6 frente a 6,9 g). La presencia de calcio no responde al criterio planteado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f478b22a-6b41-4b89-afe0-8d4145f66009', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  '74d2c01d-c62d-4040-9f6a-7e536f0b9ac4', 'Sistemas del cuerpo humano',
  'Miguel debe diseñar un menú que tenga un alimento por cada tipo de alimento y le aporte la mayor cantidad de calorías. ¿Cuál sería la mejor decisión según la tabla?',
  array['Yogurt, carne de vaca, almendras y espinaca.', 'Leche entera, carne de cerdo, nueces y alcachofas.', 'Nueces, maní, leche entera y almendras.', 'Espinacas, acelgas, yogurt y carne de vaca.'],
  'Elige un máximo por grupo sin repetir categorías.', 'publicada', 'modelo', 'c071a7eb7122a849f58af1de384b8700', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f478b22a-6b41-4b89-afe0-8d4145f66009', 1, 'La combinación elegida incluye el mayor valor de cada grupo: 490 + 375 + 600 + 50 = 1515 calorías según la tabla. Las demás reducen el total o repiten grupos y omiten otros. Las cifras son las del ejercicio y no especifican el tamaño real de las porciones.');

